name = Стенд взаимодействия
zone = character
size_chunks = 1
# ВТОРОЙ СТЕНД ЗОНЫ ФИГУРЫ (правило 17a): приёмка ПОЗ, ПОСАДКИ И ХВАТА.
#
# ПОЧЕМУ ОТДЕЛЬНО ОТ СТЕНДА ПЕРСОНАЖА. Тот меряет фигуру против ЗЕМЛИ —
# шаг, скольжение ноги, ступень, скат, стопы на предмете, — и его расстановка
# уже вошла в снятые ленты походки. Всякий новый предмет, поставленный там,
# менял бы кадры, которыми доказана походка. Здесь мерится другое утверждение:
# что фигура делает С ПРЕДМЕТОМ, а не с грунтом, и поэтому предметы стоят
# редко и порознь, а земля нарочно плоская и одна на весь стенд.
#
# ПОЧЕМУ ПЛОЩАДКА УЛИЧНАЯ, А НЕ КОМНАТА. Комната ставит стену за спиной у
# каждого предмета, и промах позы прячется в стене: нога, ушедшая сквозь пол,
# и рука, прошедшая мимо кружки, на общем плане неотличимы от тесноты. На
# открытой площадке каждый предмет обходится кругом и снимается с любой
# стороны, а свет один и тот же для всех четырёх станций.
#
# КАТЕГОРИЯ stands та же, что у стенда персонажа: MapCatalog делает категорию
# из ПАПКИ, и оба стенда стоят в списке карт одной строкой рядом.
#
# БОЕВЫЕ КАРТЫ ЭТОЙ ВОЛНОЙ НЕ ТРОНУТЫ НИ БАЙТОМ.
source = stand:Gallery
scene = assets/scenes/stands/interaction.scene
objects = assets/objects/furniture
description = Площадка приёмки поз: обеденная группа (стол, лавка, стул), отдельная лавка, кровать и стеллаж-хват с тремя высотами 0.80/1.38/1.93. Станции разнесены дальше радиуса прицела мебели, чтобы «Сесть» никогда не относилось к двум предметам сразу.
